func (s *articleFacadeImpl) GetArticle(ctx context.Context, slug string, currentUser *User) (ArticleView, error) {
	article, err := s.articleRepo.FindBySlugOrFail(ctx, slug)
	if err != nil {
		return ArticleView{}, fmt.Errorf("find article by slug: %w", err)
	}
	author, err := s.userRepo.FindAuthorByArticle(ctx, article)
	if err != nil {
		return ArticleView{}, fmt.Errorf("find author by article: %w", err)
	}
	return article.ToArticleView(author, currentUser), nil
}

