func (s *articleFacadeImpl) FindArticles(ctx context.Context, tag, authorName, favoritedByUser string, offset int64, limit int, currentUser *User) (MultipleArticlesView, error) {
    var favoritedBy, author *User
    var err error
    if favoritedByUser != "" {
        favoritedBy, err = s.userRepo.FindByUsername(ctx, favoritedByUser)
        if err != nil {
            return MultipleArticlesView{}, fmt.Errorf("find favorited by user: %w", err)
        }
    }
    if authorName != "" {
        author, err = s.userRepo.FindByUsername(ctx, authorName)
        if err != nil {
            return MultipleArticlesView{}, fmt.Errorf("find author by name: %w", err)
        }
    }
    articles, err := s.articleRepo.FindNewestArticleFilteredBy(ctx, tag, author.ID, favoritedBy, limit, offset)
    if err != nil {
        return MultipleArticlesView{}, fmt.Errorf("find articles: %w", err)
    }
    var articleViews []ArticleView
    for _, article := range articles {
        view := mapToArticleView(article, currentUser)
        articleViews = append(articleViews, view)
    }
    return toMultipleArticlesView(articleViews), nil
}

